   "id": "zfdcb66b3",
   "sez": "economia",
   "titolo": "Le pompe di calore faticano a diffondersi nelle imprese italiane: l'ostacolo principale è il costo",
   "orig": "Le pompe di calore faticano a diffondersi nelle imprese italiane: l’ostacolo principale è il costo",
   "lead": "Le pompe di calore faticano a diffondersi nelle imprese italiane, principalmente a causa dei costi elevati che frenano la transizione energetica del settore produttivo. Secondo una ricerca del Cna diffusa a Roma, solo il 13% delle aziende conosce il funzionamento di questi impianti, mentre il 42% non ha mai valutato la loro installazione. Gli operatori evidenziano che per le micro e piccole imprese l'adozione di tali tecnologie o l'elettrificazione della produzione comportano spese proibitive. Lo riferisce la Repubblica – Economia.",
   "more": [
    "Le pompe di calore utilizzano energia rinnovabile per il riscaldamento e la climatizzazione, riducendo le emissioni di gas serra rispetto ai sistemi tradizionali a combustibili fossili. Tuttavia, gli elevati costi iniziali di investimento e l'adeguamento degli impianti esistenti rappresentano spesso un ostacolo insormontabile per le piccole e medie imprese, penalizzate da margini di profitto ridotti."
   ],
   "fonti": [
    {
     "n": "la Repubblica – Economia",
     "p": "IT",
     "c": "Roma",
     "u": "https://www.repubblica.it/economia/rapporti/energitalia/sostenibilita/2026/11/03/news/le_pompe_di_calore_faticano_a_diffondersi_nelle_imprese_italiane_l_ostacolo_principale_e_il_costo-425696915/?rss",
     "angolo": "",
     "atlas": "Italy",
     "t": "2026-11-03T18:46+01:00"
    }
   ],
   "data": "3 nov",
