   "id": "z606115c2",
   "sez": "economia",
   "titolo": "Petrolio, gas e carbone crescono insieme alle rinnovabili",
   "orig": "Petrolio, gas e carbone crescono insieme alle rinnovabili",
   "lead": "Nel panorama energetico globale si assiste a una crescita parallela dei combustibili fossili, come petrolio, gas e carbone, e delle fonti rinnovabili. Secondo il rapporto Global Energy Perspective 2026 di McKinsey presentato a Roma, questa tendenza evidenzia le contraddizioni della transizione energetica, caratterizzata da una domanda mondiale in aumento, reti di distribuzione insufficienti e tensioni geopolitiche. Tali fattori rischiano di provocare un rincaro dei costi per le tecnologie pulite. Lo riferisce la Repubblica – Economia.",
   "more": [
    "La transizione energetica globale richiede ingenti investimenti nelle infrastrutture di rete e nello stoccaggio dell'energia per integrare efficacemente le fonti rinnovabili. La contemporanea crescita della domanda di energia e dei combustibili tradizionali mostra quanto sia complesso sostituire rapidamente il sistema fossile esistente, rallentando gli obiettivi di decarbonizzazione."
   ],
   "fonti": [
    {
     "n": "la Repubblica – Economia",
     "p": "IT",
     "c": "Roma",
     "u": "https://www.repubblica.it/economia/rapporti/energitalia/sostenibilita/2026/11/03/news/petrolio_gas_e_carbone_crescono_insieme_alle_rinnovabili-425696831/?rss",
     "angolo": "",
     "atlas": "Italy",
     "t": "2026-11-03T17:55+01:00"
    }
   ],
