   "id": "za1498f68",
   "sez": "economia",
   "titolo": "Aumento dei prezzi del carburante in Namibia mentre gli stipendi rimangono stagnanti",
   "orig": "Fuel hikes hit Namibians as salaries remain stagnant",
   "lead": "I cittadini della Namibia affrontano un ulteriore rincaro del costo della vita a causa di un nuovo aumento dei prezzi dei carburanti deciso dal governo. Il ministro delle Industrie, delle Miniere e dell'Energia, Modestus Amutse, ha annunciato a Windhoek un incremento di due dollari namibiani per il prezzo della benzina. Questa misura si inserisce in un contesto economico caratterizzato da salari stagnanti che non accennano a crescere. Lo riferisce The Namibian.",
   "more": [
    "L'aumento dei prezzi dei carburanti nei Paesi in via di sviluppo con economie fortemente dipendenti dall'importazione di energia genera una reazione a catena sui costi dei trasporti e dei beni di prima necessità. Quando i salari rimangono invariati, il potere d'acquisto delle famiglie diminuisce drasticamente, acuendo le disuguaglianze e le difficoltà sociali."
   ],
