   "orig": "BoG warns public of 20 unlicensed digital credit services providers",
   "lead": "La Banca centrale del Ghana, in collaborazione con l'Autorità per la cybersicurezza, ha intensificato i controlli per tutelare i consumatori nel settore del credito digitale. Ad Accra è stato diffuso un avviso ufficiale che mette in guardia la popolazione contro venti società che offrono servizi di prestito online sprovviste della necessaria autorizzazione, operando in violazione delle normative vigenti. Lo riferisce MyJoyOnline.",
