   "titolo": "North Guana Cay vicina a dieci giorni senza energia elettrica",
   "orig": "North Guana Cay nears 10 days without energy",
   "lead": "I residenti di North Guana Cay affrontano una prolungata interruzione della fornitura di energia elettrica, giunta quasi al decimo giorno consecutivo. La situazione è emersa a Nassau dopo che la società Bahamas Power & Light ha deciso di dirottare un generatore sostitutivo originariamente destinato alla comunità locale verso un'altra isola, Man-O-War Cay. Lo riferisce The Tribune (Bahamas).",
   "more": [
    "Nei piccoli arcipelaghi e nelle comunità insulari dipendenti da reti elettriche isolate, guasti prolungati ai generatori e ritardi nella logistica di sostituzione possono paralizzare i servizi essenziali e la vita quotidiana, evidenziando la fragilità delle infrastrutture energetiche periferiche."
   ],
