   "id": "zfe385840",
   "sez": "economia",
   "titolo": "Il governo portoghese valuta di concentrare la partecipazione statale nella raffineria di Sines",
   "orig": "Governo admite concentrar participação do Estado na refinaria de Sines",
   "lead": "Il governo del Portogallo sta valutando la possibilità di concentrare la partecipazione dello Stato nella raffineria di Sines. A Lisbona, la ministra dell'Ambiente e dell'Energia ha dichiarato che l'esecutivo dispone dei mezzi legali necessari per bloccare un'eventuale perdita del controllo nazionale sull'impianto strategico, a seguito del fallimento della trattativa con la società Moeve. Lo riferisce Público.",
   "more": [
    "La gestione degli asset energetici strategici e delle infrastrutture di raffinazione riveste un ruolo cruciale per la sicurezza nazionale e l'indipendenza energetica degli Stati membri dell'Unione Europea, spingendo talvolta i governi a intervenire direttamente per preservare il controllo pubblico o nazionale."
   ],
