   "titolo": "Consigliere distrettuale di Yuen Long condannato a due anni e mezzo di carcere a Hong Kong",
   "orig": "Yuen Long district councillor jailed for 2.5 years over unlawful sexual intercourse with 13-year-old girl",
   "lead": "Un consigliere distrettuale di Hong Kong, Sei Chun-hing, è stato condannato a due anni e mezzo di reclusione per aver avuto rapporti sessuali illeciti con una ragazzina di tredici anni. La sentenza è stata emessa dal tribunale distrettuale dopo che l'imputato era stato riconosciuto colpevole nel mese di settembre. Durante l'udienza, il giudice ha sottolineato la totale mancanza di rimorso da parte dell'amministratore. Lo riferisce Hong Kong Free Press.",
   "more": [
    "Le leggi penali di Hong Kong puniscono severamente i rapporti sessuali con minori di sedici anni, e i procedimenti giudiziari a carico di figure pubbliche o politici locali ricevono particolare attenzione mediatica per la gravità delle violazioni commesse."
   ],
