   "orig": "If a blue wave is coming, here are the races where it will start",
   "lead": "Le elezioni di midterm negli Stati Uniti rappresentano storicamente un test difficile per il partito del presidente in carica, ma l'attenzione si concentra sui collegi dove potrebbe concretizzarsi un'affermazione elettorale dei democratici. Da Il Cairo si evidenzia che i sondaggi della vigilia preannunciano una competizione particolarmente serrata, con i repubblicani preoccupati per l'andamento delle urne nei principali Stati chiave. Lo riferisce Egypt Independent.",
