   "orig": "Allegramente pessimista – Come si usa il potere",
   "lead": "Mercoledì 9 dicembre al teatro Oscar di Milano si tiene il quarto appuntamento della serie di spettacoli e podcast \"Allegramente pessimista. Perché l’Italia non è cambiata\", ideata da Francesco Piccolo. L'evento analizza, attraverso il film \"Indagine su un cittadino al di sopra di ogni sospetto\" di Gian Maria Volonté, le dinamiche e gli abusi legati all'esercizio del potere, piccolo o grande che sia, da parte dei cittadini italiani. Lo riferisce Il Post.",
