   "lead": "L'armata lettone ha comunicato che due droni hanno violato lo spazio aereo del Paese durante gli ultimi giorni, generando allarmi alle frontiere tra domenica e lunedì. Secondo quanto riferito, uno dei velivoli senza pilota è di provenienza russa, mentre l'altro risulta di origine ucraina. Lo riferisce HotNews.",
