   "lead": "Negli Stati Uniti, nell'ambito del progetto di sostituzione del Sagamore Bridge gestito dal Dipartimento dei Trasporti del Massachusetts, sono in corso i lavori preliminari con un programma di prove sui pali trivellati. Questa fase serve a perfezionare la progettazione finale delle fondamenta della nuova struttura situata nel Canale di Cape Cod. Lo riferisce Engineering News-Record.",
