   "lead": "I quattro partecipanti alla simulazione di un habitat marziano organizzata dalla NASA hanno concluso il loro test durato un anno, emergendo dalla struttura il 31 ottobre 2026. L'esperimento è servito a studiare le condizioni e le sfide che gli astronauti potrebbero affrontare durante una futura missione sul pianeta Marte. Lo riferisce EarthSky.",
