   "lead": "Si discute sulle modalità attraverso cui diversi leader politici gestiscono le sconfitte elettorali e il riconoscimento dei risultati, in attesa di osservare gli sviluppi politici negli Stati Uniti e le reazioni pubbliche. Il dibattito analizza i comportamenti messi in atto in contesti istituzionali complessi in relazione al potere democratico.",
