   "lead": "Negli Stati Uniti, il Dipartimento dei Trasporti ha destinato 1,24 miliardi di dollari in finanziamenti federali, provenienti dalla legge IIJA, per interventi sulla rete ferroviaria. I sussidi saranno utilizzati dai beneficiari per rimuovere i conflitti tra strade e ferrovie e per eliminare i passaggi a livello. Lo riferisce Construction Dive.",
