   "lead": "Uno studio pubblicato sulla rivista Rheumatology International evidenzia che i pazienti affetti da lupus eritematoso sistemico (SLE) presentano un rischio maggiore di incorrere in complicanze in seguito a interventi chirurgici. La ricerca analizza i fattori clinici associati a tali procedure. Lo riferisce Medical Xpress.",
