   "lead": "A Shenzhen è stata completata la costruzione della Hetao Alpha tower, un grattacielo alto 212 metri e costato circa 120 milioni di sterline. Conosciuta come torre 'Butterfly', la struttura è stata progettata dallo studio di architettura britannico RSHP e dispone di una superficie complessiva di oltre 96.000 metri quadrati. Lo riferisce Global Construction Review.",
