   "titolo": "Gli USA valutano la vendita di una quota dei diritti commerciali del Team USA per le Olimpiadi",
   "orig": "USOPC considering plan to sell stake in Team USA as LA Olympics approach",
   "lead": "Il Comitato Olimpico e Paralimpico degli Stati Uniti (USOPC) è in una fase avanzata per la creazione di un’entità incaricata di vendere una quota dei diritti commerciali del Team USA. Questa operazione mira a raccogliere capitali in vista dei Giochi Olimpici estivi di Los Angeles 2028 e invernali di Salt Lake City. Si tratterebbe di un cambiamento epocale per l’organizzazione no-profit che, a differenza di molti comitati nazionali, non riceve fondi governativi e si finanzia storicamente attraverso sponsorizzazioni e licenze commerciali. Lo riferisce The Guardian.",
   "more": [
    "L'USOPC gestisce la partecipazione degli atleti americani ai Giochi, ma opera come ente privato. La vendita di quote commerciali rappresenta una strategia per massimizzare i profitti durante il periodo in cui gli Stati Uniti ospiteranno le edizioni olimpiche, garantendo risorse a lungo termine per il sostegno delle discipline sportive e la preparazione degli atleti di alto livello."
   ],
