   "titolo": "Al Parlamento europeo arriva la mostra ANSA 'Le donne della Repubblica'",
   "orig": "Al Parlamento europeo arriva la mostra ANSA 'Le donne della Repubblica'",
   "lead": "Il 4 novembre 2024, presso il Parlamento europeo, verrà inaugurata la mostra fotografica dell'agenzia ANSA intitolata 'Le donne della Repubblica'. Il vernissage dell'esposizione si terrà alla presenza della Presidente Roberta Metsola nel corso della Gender Equality Week, una settimana dedicata alla promozione della parità di genere nelle istituzioni. L'iniziativa celebra il ruolo fondamentale delle donne nella storia italiana, offrendo una prospettiva visiva sul loro contributo alla crescita democratica del Paese in un contesto istituzionale internazionale. Lo riferisce ANSA.",
   "more": [
    "La Gender Equality Week è un'iniziativa del Parlamento europeo volta a sensibilizzare i cittadini e i decisori politici sull'importanza di colmare il divario di genere in ogni settore della società. Attraverso mostre, dibattiti e workshop, le istituzioni comunitarie promuovono i valori di uguaglianza e parità salariale sanciti dai trattati fondamentali dell'Unione."
   ],
