   "sez": "salute",
   "titolo": "In futuro un esame del sangue potrebbe sostituire le biopsie",
   "orig": "In the future, a blood test may be able to replace a biopsy",
   "lead": "Il ricercatore biomedico Danilo Mladenović sta sviluppando una tecnica presso l’Università di Tallinn per sostituire le tradizionali biopsie tissutali con semplici esami del sangue. La ricerca mira a estrarre informazioni cruciali sull’interno dei tumori o di altri organi malati direttamente da un campione ematico, facilitando una diagnosi più precoce delle patologie. Questo metodo permetterebbe inoltre di monitorare l'efficacia delle terapie senza sottoporre i pazienti a prelievi di tessuto ripetuti e invasivi, migliorando significativamente la tempestività del trattamento. Lo riferisce Medical Xpress.",
   "more": [
    "Le cosiddette 'biopsie liquide' rappresentano una frontiera avanzata della medicina oncologica. Questa tecnologia si basa sulla rilevazione nel sangue di frammenti di DNA tumorale o di cellule cancerose circolanti, permettendo di ottenere una mappatura genetica della malattia senza dover ricorrere a interventi chirurgici, con minori rischi per il paziente e costi potenzialmente più contenuti."
   ],
