   "id": "zf0a681b6",
   "sez": "tech",
   "titolo": "Attacco Cyber, Galasso: \"Stabilire l'origine è impossibile\"",
   "orig": "Attacco Cyber, Galasso: \"Stabilire origine è impossibile\"",
   "lead": "Gianluca Galasso, direttore del Servizio Operazioni dell'Agenzia per la Cybersicurezza Nazionale (ACN), ha dichiarato che risalire con certezza all'origine degli attacchi informatici è un'operazione quasi impossibile. Secondo il funzionario, gli aggressori utilizzano sofisticate tecniche di offuscamento per mascherare gli indirizzi IP di provenienza, che possono apparire come generati in qualsiasi nazione del mondo. Le parole di Galasso arrivano in un momento di elevata allerta per le infrastrutture digitali nazionali, evidenziando come l'anonimato resti una delle armi principali degli hacker. Lo riferisce Sky TG24.",
   "more": [
    "L'attribuzione degli attacchi informatici è una sfida costante per le autorità di intelligence. Gli hacker utilizzano spesso reti proxy, server VPN e computer infetti (botnet) situati in Paesi terzi per occultare le proprie tracce. Questo rende estremamente difficile collegare formalmente un attacco a un gruppo specifico o a uno Stato, complicando le risposte diplomatiche o legali."
   ],
   "fonti": [
    {
     "n": "Sky TG24",
     "p": "IT",
     "c": "Roma",
     "u": "https://tg24.sky.it/politica/video/2026/11/03/attacco-cyber-galasso-stabilire-origine-impossibile-1137093",
     "angolo": "",
     "atlas": "Italy",
     "t": "2026-11-03T18:59+00:00"
    }
   ],
   "data": "3 nov",
