   "id": "zdfd71571",
   "sez": "cultura",
   "titolo": "Il film 'La bola negra' diventa il terzo maggior incasso di sempre in Spagna",
   "orig": "La bola negra becomes Spain's third highest-grossing film ever",
   "lead": "Il lungometraggio 'La bola negra', diretto dai registi Javier Calvo e Javier Ambrossi, ha raggiunto la cifra record di 36,7 milioni di euro al botteghino, diventando il terzo film con il maggior incasso nella storia del cinema spagnolo. La pellicola si posiziona ora dietro soltanto ai kolossal 'Spanish Affair' e 'The Impossible' nella classifica dei successi nazionali di tutti i tempi. Questo traguardo conferma lo straordinario impatto culturale e commerciale dell'opera dei due registi, consolidando il loro prestigio nell'industria cinematografica europea. Lo riferisce Euronews.",
   "more": [
    "L'industria cinematografica spagnola ha vissuto una fase di grande dinamismo negli ultimi anni, con produzioni capaci di competere con i blockbuster internazionali. Successi come questo sono spesso sostenuti da una forte distribuzione e dal riconoscimento critico, contribuendo a consolidare il prestigio del cinema iberico a livello globale e incentivando nuovi investimenti nel settore audiovisivo da parte di piattaforme e produttori indipendenti."
   ],
