   "id": "ze5d3a74a",
   "sez": "salute",
   "titolo": "Militari EUFOR feriti trasferiti in Italia per cure mediche",
   "orig": "Injured EUFOR Personnel sent to Italy for Medical Treatment",
   "lead": "Otto membri del personale EUFOR, rimasti feriti alcuni giorni fa nello schianto di un elicottero a Gorice, sono stati trasferiti dalla Bosnia-Erzegovina in Italia per ricevere ulteriori cure specialistiche. Dopo essere stati assistiti presso il centro sanitario di Brčko, i militari sono stati trasportati a Tuzla a bordo di veicoli medici militari e da lì imbarcati su un volo speciale per l'Italia. L'operazione è stata coordinata per garantire ai feriti l'accesso a trattamenti ospedalieri adeguati alla gravità delle loro condizioni dopo l'incidente aereo. Lo riferisce Sarajevo Times.",
   "more": [
    "La missione EUFOR Althea è un'operazione militare dell'Unione Europea in Bosnia-Erzegovina finalizzata a garantire la stabilità e la sicurezza della regione. In caso di incidenti gravi, è prassi comune evacuare il personale ferito verso Paesi con strutture mediche avanzate o verso le nazioni di origine per assicurare il miglior percorso di riabilitazione possibile."
   ],
