   "id": "z8919e51d",
   "sez": "salute",
   "titolo": "Sudafrica, i vaccini per l'mpox saranno distribuiti mentre i casi salgono a 26",
   "orig": "SPOTLIGHT: Mpox vaccine stock ‘will be deployed as needed’ as cases climb to 26",
   "lead": "In Sudafrica le scorte di vaccino contro il vaiolo delle scimmie (mpox) verranno distribuite in base alle necessità, mentre il numero totale di casi confermati nel Paese è salito a 26. La maggior parte dei contagi, precisamente 20 episodi, è stata registrata a partire dal mese di agosto, con una forte concentrazione nella provincia del Capo Occidentale. Le autorità sanitarie monitorano l'evoluzione del virus e valutano quante dosi di vaccino donate rimangano effettivamente a disposizione della popolazione per contrastare la diffusione e proteggere i soggetti a rischio. Lo riferisce Daily Maverick.",
   "more": [
    "L'mpox è una malattia virale che può causare febbre, dolori muscolari e caratteristiche eruzioni cutanee. L'attuale aumento dei casi in diverse parti del mondo ha spinto le organizzazioni sanitarie a promuovere campagne di vaccinazione mirate, utilizzando scorte spesso donate da Paesi con maggiori risorse per contenere i focolai ed evitare che la malattia diventi endemica."
   ],
