   "id": "z32821bc4",
   "sez": "salute",
   "titolo": "Gestione della salute in azienda: la governance prima del contratto",
   "orig": "Ambulatório e equipe de saúde terceirizada: governança antes do contrato",
   "lead": "In Brasile si discute dell'importanza della governance prima di avviare cliniche aziendali con personale esternalizzato. Aprire un ambulatorio interno può sembrare una semplice questione di spazio e orari, ma i rischi aumentano se non si definiscono prima le responsabilità tecniche, le licenze necessarie e i protocolli per le emergenze. Gli esperti sottolineano che garantire la continuità assistenziale e la corretta gestione delle cartelle cliniche è fondamentale per la sicurezza dei dipendenti. La scelta di esternalizzare richiede dunque un controllo rigoroso sulla qualità del servizio fornito. Lo riferisce G1.",
   "more": [
    "La medicina del lavoro si occupa di prevenire malattie e infortuni legati all'attività professionale. In molte grandi aziende, la presenza di ambulatori interni migliora il benessere dei lavoratori e riduce l'assenteismo, ma richiede l'osservanza di rigide normative sanitarie e sulla privacy dei dati medici per tutelare i diritti dei dipendenti e la responsabilità legale dell'impresa."
   ],
