   "id": "z493de841",
   "sez": "dibattito",
   "titolo": "In Portogallo si chiede cautela sugli affitti per anziani e persone vulnerabili",
   "orig": "CES pede cautela nas rendas de idosos e vulneráveis em risco de perda da habitação",
   "lead": "In Portogallo si discute della protezione degli inquilini anziani e vulnerabili di fronte al rischio di perdere la propria abitazione a causa dell'aumento dei canoni. Il Consiglio Economico e Sociale (CES) ha chiesto cautela negli incrementi delle rendite e nelle mancate rinnovazioni dei contratti di locazione che potrebbero colpire le fasce più fragili della popolazione. Secondo il CES, è inoltre urgente che le autorità pubblichino un elenco completo degli immobili pubblici urbani che risultano attualmente inutilizzati o in stato di abbandono per valutare possibili soluzioni abitative alternative. Lo riferisce RTP.",
   "more": [
    "Il mercato degli affitti in Europa è stato fortemente influenzato negli ultimi anni dalla crescita del turismo e dalla gentrificazione, portando a rincari che spesso superano l'aumento dei salari. Molti governi europei stanno cercando un equilibrio tra il diritto di proprietà e la protezione sociale degli inquilini, introducendo tutele per prevenire che le fasce deboli della popolazione finiscano in condizioni di povertà o senza fissa dimora."
   ],
