   "id": "zfe43a058",
   "sez": "economia",
   "titolo": "Dal 4 novembre operativa la carta «Dedicata a te» con un contributo di 500 euro",
   "orig": "Dal 4 novembre operativa la carta «Dedicata a te»: 500 euro per acquisti alimentari",
   "lead": "Dal 4 novembre 2024 diventa operativa la nuova carta 'Dedicata a te', un contributo di 500 euro destinato alle famiglie con ISEE inferiore a 15.000 euro per l'acquisto di beni alimentari di prima necessità, carburanti o abbonamenti ai trasporti. Oltre un milione di nuclei familiari riceveranno la somma direttamente sulla propria carta prepagata PostePay, già distribuita nelle scorse edizioni o ritirabile presso gli uffici postali per i nuovi beneficiari identificati dai comuni. La misura punta a sostenere il potere d'acquisto dei cittadini più fragili contro il carovita. Lo riferisce Il Sole 24 Ore.",
   "more": [
    "La carta 'Dedicata a te' è una misura di sostegno al reddito introdotta per contrastare l'inflazione e l'aumento dei costi dei beni di prima necessità. Si rivolge ai nuclei familiari più esposti alla crisi economica, con criteri di assegnazione basati sull'ISEE e sulla presenza di minori. Questo tipo di interventi mira a sostenere i consumi interni fornendo un aiuto diretto e vincolato all'acquisto di categorie merceologiche specifiche."
   ],
