   "id": "zbb63b3de",
   "sez": "economia",
   "titolo": "Il potere nascosto dell'elettricità e la fattibilità della transizione energetica",
   "orig": "The hidden power of electricity",
   "lead": "La transizione energetica globale verso fonti più pulite non è un'impresa impossibile come spesso viene rappresentata nel dibattito pubblico. Secondo un’analisi economica, le innovazioni tecnologiche e il potenziale dell'elettricità stanno rendendo il passaggio alle rinnovabili più fattibile e sostenibile di quanto si potesse prevedere in passato. Superare la dipendenza dai combustibili fossili richiede investimenti mirati e una revisione delle infrastrutture, ma i progressi attuali suggeriscono che gli obiettivi di decarbonizzazione siano realmente raggiungibili con il giusto coordinamento tra politica e mercati. Lo riferisce Financial Times.",
   "more": [
    "L'elettrificazione dei consumi è considerata il pilastro principale della lotta al cambiamento climatico. Sostituire i motori a combustione e i sistemi di riscaldamento a gas con alternative elettriche alimentate da fonti rinnovabili permette di ridurre drasticamente le emissioni di CO2, migliorando contemporaneamente l'efficienza energetica e riducendo la dipendenza geopolitica dai produttori di idrocarburi."
   ],
   "fonti": [
    {
     "n": "Financial Times",
     "p": "UK",
     "c": "Londra",
     "u": "https://www.ft.com/content/1a40a3af-933b-4c12-aa9b-2cf89f2ed139?syn-25a6b1a6=1",
     "angolo": "",
     "atlas": "United Kingdom",
     "t": "2026-11-03T17:17+00:00"
    }
   ],
   "data": "3 nov",
