   "id": "z933dea8b",
   "sez": "economia",
   "titolo": "Azienda della Georgia paga 220mila dollari per un terreno inesistente",
   "orig": "Georgia firm pays $220,000 for nonexistent land, loses bid for refund",
   "lead": "La società Talon Assets ha perso il ricorso per ottenere il rimborso di 220.000 dollari versati per l’acquisto di un terreno ad Atlanta che si è poi rivelato inesistente. La proprietà era stata acquisita durante un'asta fiscale della contea di Fulton, ma le autorità hanno respinto la richiesta di rimborso invocando l'immunità sovrana come difesa legale. La Corte d'Appello della Georgia ha confermato il licenziamento del caso, sottolineando le enormi difficoltà legali che i privati incontrano nel perseguire rivendicazioni finanziarie contro le amministrazioni locali negli Stati Uniti. Lo riferisce Times of India.",
   "more": [
    "L'immunità sovrana è un principio giuridico che protegge lo Stato e le sue articolazioni amministrative dall'essere citati in giudizio senza il loro consenso. Sebbene esistano delle eccezioni, in molti ordinamenti americani questo concetto rende difficile per i cittadini e le imprese ottenere risarcimenti per errori burocratici o negligenze commesse dagli enti pubblici, specialmente in transazioni immobiliari complesse."
   ],
