   "id": "zf41ebcb9",
   "sez": "economia",
   "titolo": "India, vedova riceve sgravi fiscali per depositi in contanti contestati",
   "orig": "Widow faces tax notice for Rs 60 lakh cash deposits; why ITAT gave ‘gift’ relief",
   "lead": "Il Tribunale d’Appello per le Imposte sul Reddito (ITAT) in India ha concesso un’agevolazione fiscale a una vedova che aveva ricevuto un avviso di accertamento per depositi in contanti pari a 60 lakh di rupie. Il Dipartimento del Fisco aveva contestato i versamenti effettuati nel 2015-16 poiché la donna non aveva presentato la dichiarazione dei redditi. Tuttavia, i giudici hanno riconosciuto la natura di sostegno familiare o regalo ai fondi ricevuti, annullando l'ordine emesso dall'ufficiale accertatore che aveva agito dopo il mancato riscontro alla notifica iniziale. Lo riferisce Times of India.",
   "more": [
    "In India, il controllo sui grandi depositi in contanti è diventato molto rigido, specialmente dopo la politica di demonetizzazione del 2016. Le autorità fiscali monitorano i flussi finanziari non dichiarati, ma la magistratura tributaria può intervenire per proteggere i contribuenti se viene dimostrato che le somme derivano da fonti lecite, come aiuti parentali, che non costituiscono reddito tassabile secondo la legge vigente."
   ],
