   "id": "zb2c3e07e",
   "sez": "economia",
   "titolo": "Il Nepal ha vent'anni per sfruttare il dividendo demografico giovanile",
   "orig": "Nepal has two decades to turn its youth bulge into an economic dividend, World Bank reports",
   "lead": "Secondo un rapporto della Banca Mondiale, il Nepal dispone di una finestra temporale di circa vent'anni per trasformare l'attuale picco di popolazione giovanile in un dividendo economico significativo. Tuttavia, la debole crescita dell'occupazione interna, la forte dipendenza dalle rimesse degli emigrati e la fragilità delle reti di sicurezza sociale minacciano seriamente questa opportunità. Senza riforme strutturali e investimenti mirati nella creazione di posti di lavoro, il Paese rischia di non riuscire a capitalizzare la sua risorsa più preziosa prima che l'invecchiamento della popolazione cambi nuovamente gli equilibri economici nazionali. Lo riferisce The Kathmandu Post.",
   "more": [
    "Il dividendo demografico si verifica quando la quota di popolazione in età lavorativa è superiore a quella dipendente (bambini e anziani). Questa condizione può accelerare la crescita economica se il mercato del lavoro è in grado di assorbire la manodopera; in caso contrario, l'eccesso di giovani disoccupati può generare instabilità sociale e spingere a un'emigrazione di massa, privando il Paese delle proprie energie migliori."
   ],
