   "id": "z0a1a50ba",
   "sez": "economia",
   "titolo": "Filippine, i gruppi di Razon e Ang guidano le gare per l'energia dai rifiuti",
   "orig": "Razon, Ang groups lead waste-to-energy bids",
   "lead": "Le società sostenute dai magnati Enrique Razon Jr. e Ramon Ang sono tra i nove gruppi in lizza per aggiudicarsi i contratti governativi nelle Filippine per la realizzazione di progetti di trasformazione dei rifiuti in energia (WTE). Il Dipartimento dell'Energia ha identificato i potenziali vincitori dell'asta speciale, che mira a sviluppare nuove capacità produttive nazionali. Queste infrastrutture sono progettate per risolvere contemporaneamente il problema della gestione dei rifiuti urbani e la necessità di diversificare le fonti energetiche del Paese attraverso soluzioni tecnologiche innovative e sostenibili. Lo riferisce Philippine Daily Inquirer.",
   "more": [
    "La tecnologia waste-to-energy permette di produrre elettricità o calore attraverso il trattamento termico dei rifiuti. Nelle economie in rapida crescita come quella filippina, questi impianti sono visti con favore per ridurre la dipendenza dalle discariche e migliorare l'indipendenza energetica, sebbene richiedano rigorosi controlli ambientali per limitare l'emissione di sostanze inquinanti nell'atmosfera."
   ],
