   "id": "zf469acba",
   "sez": "economia",
   "titolo": "AboitizPower acquisisce il 60% di una società di Bukidnon per il solare",
   "orig": "AboitizPower to acquire 60% stake in Bukidnon firm",
   "lead": "Aboitiz Power Corp. ha annunciato l'acquisizione di una quota del 60% in una società di Bukidnon per potenziare il proprio settore delle energie rinnovabili nelle Filippine. Attraverso la controllata Aboitiz Renewables Inc., l'azienda ha stretto una collaborazione con A Brown Co. Inc. per lo sviluppo di un impianto integrato che combina una centrale solare da 191 megawatt con un sistema di accumulo a batterie. Questo progetto rappresenta un passo importante verso la decarbonizzazione del mix energetico nazionale, puntando sulla capacità di stoccaggio per stabilizzare la fornitura di energia pulita. Lo riferisce Philippine Daily Inquirer.",
   "more": [
    "L'integrazione di sistemi di batterie (BESS) negli impianti solari è fondamentale per superare l'intermittenza della produzione di energia rinnovabile. Questo permette di accumulare l'elettricità prodotta durante le ore di sole e di rilasciarla quando la domanda aumenta o la produzione cala, rendendo la rete elettrica più stabile e meno dipendente dalle centrali a combustibili fossili."
   ],
