   "id": "z96c04ebe",
   "sez": "italia",
   "titolo": "Critiche a Meloni sull'azzardo: dai dubbi del 2015 alle nuove estrazioni",
   "orig": "Meloni cambia idea su azzardo e ludopatia: nel 2015 sosteneva che “il gioco produce miseria e povertà”. Ora il suo governo fa cassa con slot machine e gratta e vinci",
   "lead": "Il governo guidato da Giorgia Meloni è oggetto di critiche per il cambio di rotta sulle politiche riguardanti l'azzardo, avendo introdotto nuovi Gratta e vinci e un'ulteriore estrazione settimanale per Lotto e SuperEnalotto. Nel 2015, Meloni esprimeva posizioni contrarie, sottolineando come il gioco producesse miseria e povertà, mentre oggi l'esecutivo sembra utilizzare il settore per incrementare le entrate statali. L'Agenzia delle dogane e dei monopoli ha lanciato nuovi titoli di gioco con premi fino a 5 milioni di euro, alimentando il dibattito sulla coerenza delle politiche contro la ludopatia. Lo riferisce Il Fatto Quotidiano.",
   "more": [
    "Il gioco d'azzardo patologico rappresenta una sfida sanitaria significativa, con costi sociali legati alla perdita di risparmi e al disagio familiare. In Italia, lo Stato gestisce il settore tramite monopoli, cercando un equilibrio precario tra la necessità di gettito fiscale e la tutela della salute pubblica, spesso ricorrendo a campagne di sensibilizzazione che però si scontrano con l'aumento dell'offerta di gioco legale."
   ],
