   "id": "zde170fe9",
   "sez": "italia",
   "titolo": "La storica sede del Pci a Roma trasformata in un albergo a cinque stelle",
   "orig": "Botteghe Oscure, da sede del Pci a hotel a 5 stelle",
   "lead": "Lo storico palazzo di via delle Botteghe Oscure a Roma, noto per essere stato per decenni la sede nazionale del Partito Comunista Italiano, è stato riconvertito in un albergo di lusso a cinque stelle. Gli ambienti in cui lavorarono storici dirigenti come Enrico Berlinguer ospitano ora camere ed esposizioni d'arte riservate alla clientela turistica, offrendo viste panoramiche sulla capitale. Il progetto ha ripensato gli spazi interni preservando la memoria architettonica dell'edificio simbolo della politica italiana del Novecento. Lo riferisce ANSA.",
   "more": [
    "Il palazzo di via delle Botteghe Oscure ha rappresentato per gran parte del secondo Novecento il centro operativo del PCI. La riconversione immobiliare degli edifici storici della capitale risponde al forte incremento della domanda turistica di alta gamma a Roma."
   ],
