   "sez": "prima",
   "titolo": "Ricorso alla Corte Suprema contro il divieto dei social sotto i 16 anni in Australia",
   "orig": "Australia’s High Court hears bid to overturn under-16s social media ban",
   "lead": "La piattaforma Reddit e l'organizzazione Digital Freedom Project hanno presentato un ricorso alla High Court australiana per annullare il divieto d'uso dei social network ai minori di 16 anni. I ricorrenti sostengono che la misura approvata dal parlamento imponga restrizioni incostituzionali, violando il diritto di comunicazione politica garantito agli adolescenti. Le udienze dinanzi ai giudici dovranno stabilire se la tutela dei minorenni possa giustificare una limitazione dell'accesso ai servizi online.",
   "more": [
    "La legge approvata dalle autorità australiane punta a ridurre la dipendenza e laCYBER-bullismo tra i giovanissimi limitando l'uso delle piattaforme online. L'esito del processo davanti alla Corte Suprema costituisce un precedente giuridico fondamentale per i governi interessati a varare analoghe restrizioni sui social media."
   ],
