   "id": "z55f5c928",
   "sez": "viaggi",
   "titolo": "Il Museo Van Gogh di Amsterdam conserva 200 capolavori dell'artista",
   "orig": "È la più grande collezione al mondo di Van Gogh: non troverai i Girasoli, ma 200 capolavori del genio sfortunato",
   "lead": "Il Museo Van Gogh di Amsterdam, situato nella capitale olandese tra canali e case colorate, ospita la più grande collezione al mondo dedicata al celebre pittore. La struttura conserva ben duecento capolavori dell'artista sfortunato, rappresentando una delle principali attrazioni turistiche della città e una tappa obbligatoria per i visitatori. Pur non esponendo il celebre dipinto dei Girasoli, la ricca esposizione permanente nel quartiere dei musei permette di ripercorrere l'intera traiettoria artistica del maestro post-impressionista. Lo riferisce Turisti per Caso.",
   "more": [
    "Vincent van Gogh è stato uno dei più celebri e influenti pittori della storia dell'arte occidentale. Attraverso uno stile caratterizzato da pennellate vigorose e colori vivaci, l'artista olandese ha espresso intense emozioni, trasformando il panorama artistico di fine Ottocento pur ottenendo un riconoscimento quasi esclusivamente postumo per le sue opere."
   ],
