   "titolo": "La ricetta tradizionale per preparare le cozze gratinate alla pugliese",
   "orig": "Cozze gratinate",
   "lead": "Le cozze gratinate alla pugliese rappresentano un antipasto di mare semplice e gustoso, ideato per valorizzare le qualità del rinomato mollusco. La preparazione della ricetta offre una modalità alternativa e tradizionale per gustare il prodotto ittico, combinando ingredienti tipici della gastronomia regionale italiana. Il piatto si distingue per la sua facilità di esecuzione, risultando particolarmente adatto come apertura per pranzi e cene a base di pesce. Lo riferisce La Cucina Italiana.",
   "more": [
    "La cucina pugliese fa ampio uso dei prodotti ittici dell'Adriatico e dello Ionio, abbinandoli spesso a pane grattugiato, erbe aromatiche, aglio e olio extravergine d'oliva. La gratinatura al forno permette di creare una crosticina dorata mantenendo la morbidezza del mollusco al suo interno."
   ],
