   "sez": "ambiente",
   "titolo": "Namibia Wildlife Resorts investe oltre 500.000 dollari in estintori nei propri complessi",
   "orig": "NWR invests over N$500 000 in fire extinguisher installations across resorts",
   "lead": "La società Namibia Wildlife Resorts ha stanziato oltre 500.000 dollari namibiani per installare nuovi estintori in tutti i propri complessi turistici, con l'obiettivo di rafforzare la sicurezza antincendio e la gestione delle emergenze. L'intervento segue le inchieste giornalistiche di The Namibian, che avevano segnalato come gli estintori del Parco Nazionale Etosha non venissero revisionati dal 2023 e avevano contestato la mancata manutenzione dei dispositivi al resort di Sesriem durante un grave incendio nel dicembre 2025. Lo riferisce The Namibian.",
   "more": [
    "La sicurezza antincendio nelle strutture ricettive situate all'interno dei parchi naturali è fondamentale per proteggere l'incolumità dei visitatori e la fauna locale. La manutenzione regolare degli estintori e il rispetto dei protocolli di emergenza prevengono il propagarsi di roghi incontrollati in ecosistemi fragili."
   ],
