   "titolo": "Citrus Training inaugura un nuovo centro di formazione da 2 milioni di sterline a Londra",
   "orig": "Citrus opens £2m London training centre",
   "lead": "La società Citrus Training ha inaugurato un nuovo centro di formazione a Dagenham, nella zona est di Londra, con una capienza di 120 persone. La struttura sostituisce una sede più piccola precedentemente situata a Brentwood ed è stata realizzata grazie a un investimento di oltre due milioni di sterline. Il nuovo polo consentirà di ampliare la capacità ricettiva e di migliorare la qualità dei percorsi formativi offerti dall'azienda. Lo riferisce Construction Index.",
   "more": [
    "L'investimento in centri di formazione dedicati al settore delle costruzioni e dell'ingegneria risponde alla crescente domanda di competenze tecniche qualificate e norme di sicurezza nei cantieri. L'ammodernamento delle infrastrutture didattiche permette di preparare i lavoratori a standard operativi sempre più elevati."
   ],
