   "titolo": "Dichiarazione dell'UE sull'allineamento di Paesi terzi alle sanzioni per l'Ucraina",
   "orig": "Statement by the HR on behalf of the EU on the alignment of certain third countries concerning restrictive measures in respect of actions undermining or threatening the territorial integrity, sovereignty and independence of Ukraine.",
   "lead": "L'Alto rappresentante dell'Unione europea ha rilasciato una dichiarazione a nome dell'UE in merito all'allineamento di alcuni Paesi terzi alle misure restrittive adottate in risposta alle azioni che minacciano o compromettono l'integrità territoriale, la sovranità e l'indipendenza dell'Ucraina. La nota ufficiale conferma l'adesione di Stati partner al quadro sanzionatorio stabilito dalle istituzioni europee nei confronti dei soggetti responsabili dell'aggressione armata e delle violazioni del diritto internazionale nel contesto del conflitto in corso. Lo riferisce Consiglio dell'Unione europea.",
   "more": [
    "L'allineamento dei Paesi terzi alle sanzioni dell'Unione Europea rappresenta uno strumento chiave per rafforzare l'efficacia delle misure restrittive commerciali ed economiche. La cooperazione diplomatica con Stati non comunitari mira a prevenire l'aggiramento delle sanzioni e a mantenere una posizione unitaria a sostegno della sovranità territoriale ucraina."
   ],
