   "id": "z04e127b0",
   "sez": "ambiente",
   "titolo": "Le ONG portoghesi denunciano la mancanza di fondi per la natura nel bilancio 2027",
   "orig": "Quanto investe Portugal na natureza? As ONG dizem que o OE2027 não responde",
   "lead": "Le organizzazioni non governative ambientali Quercus, WWF e Zero hanno espresso forti perplessità sul bilancio statale del Portogallo per il 2027, sostenendo che non risponda alle esigenze di tutela della natura. Sebbene il Ministero dell'Ambiente abbia stanziato un milione di euro all'anno per la conservazione del lince e abbia velocizzato i risarcimenti per gli attacchi dei lupi, le associazioni denunciano la mancanza di fondi chiaramente identificabili per il ripristino degli ecosistemi naturali. Le ONG chiedono una pianificazione finanziaria più adeguata e trasparente per la biodiversità. Lo riferisce Público.",
   "more": [
    "La protezione delle specie a rischio come il lince iberico e il lupo richiede investimenti costanti sia per la conservazione della fauna sia per la gestione dei conflitti con le attività umane. Il ripristino della natura necessita di risorse dedicate per recuperare habitat degradati e adempiere alle direttive europee sulla biodiversità."
   ],
