   "id": "z3cf7eff1",
   "sez": "cultura",
   "titolo": "Il termine mogging eletto parola dell'anno dal dizionario Collins",
   "orig": "'Mogging' is Collins' word of the year... but do you know what it means?",
   "lead": "Il dizionario Collins ha eletto \"mogging\" come parola dell'anno, posizionandola in cima alla lista dei dieci vocaboli più rilevanti e popolari celebrati dall'istituzione linguistica. Il termine slang indica l'atto di eclissare, superare o mettere in ombra qualcun altro per fascino, abilità o prestazioni generali. L'espressione, diffusasi principalmente tra le nuove generazioni e sulle piattaforme social, riflette l'evoluzione costante della lingua inglese e il forte impatto della cultura digitale nel linguaggio quotidiano.",
   "more": [
    "L'elezione della parola dell'anno da parte dei principali dizionari analizza miliardi di vocaboli emersi nel dibattito pubblico e nei social media. L'ingresso di termini gergali nel Lessico Collins evidenzia come la comunicazione online plasmi rapidamente il linguaggio giovanile e la percezione sociale dei comportamenti estetici e competitivi."
   ],
