   "sez": "tech",
   "titolo": "OpenAI nomina l'ex segretario dell'Esercito USA Dan Driscoll consigliere per la sicurezza",
   "orig": "OpenAI hires Dan Driscoll, former US Army secretary who took part in Ukraine peace talks",
   "lead": "La società di intelligenza artificiale OpenAI, sviluppatrice di ChatGPT, ha assunto l'ex segretario dell'Esercito degli Stati Uniti Dan Driscoll nell'incarico di consigliere senior per l'ammodernamento della sicurezza nazionale. Driscoll, che in passato ha partecipato anche a colloqui di pace riguardanti il conflitto in Ucraina, metterà la propria esperienza al servizio dell'azienda per gestire i rapporti istituzionali e le strategie legate alla difesa tecnologica. La nomina è stata ufficializzata tramite una nota pubblicata sul sito web della compagnia. Lo riferisce Meduza.",
   "more": [
    "L'integrazione delle tecnologie di intelligenza artificiale nei settori strategici della difesa e della sicurezza nazionale è un tema cruciale per le grandi aziende tecnologiche. Il reclutamento di figure con un alto profilo istituzionale e militare consente di sviluppare soluzioni avanzate in linea con le esigenze dei governi e delle forze armate."
   ],
