   "titolo": "Uzbekistan: Apple è il principale contribuente fiscale tra le aziende digitali estere",
   "orig": "Apple pays the most tax among foreign digital service providers in Uzbekistan",
   "lead": "Tra il mese di gennaio e quello di settembre del 2026, i fornitori stranieri di servizi elettronici che operano in Uzbekistan hanno versato complessivamente 232,8 miliardi di soum in imposte, pari a circa 19,5 milioni di dollari. Il dato segna una crescita dell'85% rispetto allo stesso periodo dell'anno precedente. Tra le 109 aziende estere registrate nel Paese asiatico, i contributi più elevati sono stati versati da colossi tecnologici come Apple, Google e Meta, con la società di Cupertino al primo posto.",
   "more": [
    "Negli ultimi anni diversi Paesi hanno introdotto normative fiscali specifiche per tassare i servizi digitali offerti da multinazionali estere sul proprio territorio. Questo tipo di tassazione mira a garantire che le entrate generate dai consumatori locali vengano parzialmente restituite al fisco nazionale."
   ],
