   "id": "zb456e36f",
   "sez": "economia",
   "titolo": "Royal Mail svela la collezione di francobolli dedicati al Natale 2026",
   "orig": "Christmas 2026 stamps unveiled by Royal Mail",
   "lead": "La società postale britannica Royal Mail ha presentato la nuova serie annuale di francobolli per le festività natalizie del 2026. La collezione è composta da cinque francobolli speciali le cui illustrazioni raffigurano scene tradizionali della Natività, raccontando la storia della nascita di Gesù Cristo. I francobolli saranno messi in circolazione in tutto il Regno Unito per affrancare la corrispondenza e gli auguri di Natale inviati da cittadini e collezionisti nel periodo delle festività.",
   "more": [
    "L'emissione dei francobolli natalizi è una tradizione consolidata per l'operatore postale britannico, introdotta per la prima volta negli anni Sessanta. Tali edizioni speciali uniscono il valore filatelico al sostegno delle consuetudini culturali legate all'invio della corrispondenza augurale."
   ],
