   "sez": "economia",
   "titolo": "Banca Centrale Europea: i ministri UE discuteranno i candidati alla presidenza il 9 novembre",
   "orig": "Kandidatus į ECB vadovo postą ES ministrai aptars pirmadienį",
   "lead": "Gli Stati membri dell'Unione Europea hanno tempo fino a venerdì per presentare i nomi dei candidati alla presidenza della Banca Centrale Europea, in vista dell'uscita di scena dell'attuale presidente Christine Lagarde. Successivamente, il 9 novembre, i ministri delle Finanze dei Paesi UE si riuniranno per esaminare e discutere i profili proposti. Le scadenze ufficiali e il calendario delle consultazioni comunitarie per la successione ai vertici dell'istituto monetario di Francoforte sono stati confermati da un portavoce dell'Unione. Lo riferisce LRT.",
   "more": [
    "La Banca Centrale Europea gestisce la politica monetaria dei Paesi dell'eurozona con l'obiettivo primario di mantenere la stabilità dei prezzi. La nomina del presidente richiede una complessa decisione politica concordata tra i governi degli Stati membri dell'Unione."
   ],
