   "sez": "mondo",
   "titolo": "Egitto e Sudan firmano un accordo sulla sicurezza idrica e respingono le azioni dell'Etiopia",
   "orig": "Egypt-Sudan sign agreement to defend water security",
   "lead": "Egitto e Sudan hanno sottoscritto un accordo congiunto per difendere la propria sicurezza idrica, ribadendo la totale contrarietà a qualsiasi azione unilaterale nel bacino del Nilo orientale. I due Paesi hanno sottolineato che la gestione unilaterale della Grande Diga della Rinascita Etiopica da parte dell'Etiopia violerebbe il diritto internazionale e rappresenterebbe una minaccia persistente per gli Stati situati a valle del fiume. Durante i colloqui sono stati riaffermati i diritti storici sulle acque stabiliti dagli accordi del 1959.",
   "more": [
    "La gestione delle acque del fiume Nilo è fonte di accese controversie diplomatiche tra l'Etiopia e i Paesi situati a valle. L'Egitto e il Sudan temono che il riempimento e il funzionamento della grande diga etiopica riducano la disponibilità idrica essenziale per l'agricoltura e l'approvvigionamento della popolazione."
   ],
