   "sez": "mondo",
   "titolo": "Corea del Sud: il capo di stato maggiore visita i soldati feriti da una mina nella DMZ",
   "orig": "JCS chief pays visit to console soldiers injured in DMZ blast",
   "lead": "Il generale Jin Yong-sung, capo dello Stato Maggiore Congiunto della Corea del Sud, si è recato in visita presso la struttura ospedaliera per confortare i militari sudcoreani rimasti feriti a causa di un'esplosione. L'incidente è stato causato dal detonamento di mine antiuomo collocate dalla Corea del Nord all'interno della Zona Smilitarizzata che separa i due Paesi. Il vertice militare ha espresso il proprio sostegno ai soldati coinvolti ed espresso il proprio cordoglio per il ferimento subito durante le attività di pattugliamento.",
   "more": [
    "La Zona Smilitarizzata tra le due Coree è una delle strisce di terra più militarizzate al mondo. Nonostante il nome, l'area è disseminata di mine terrestri e postazioni difensive, rimanendo teatro di frequenti tensioni tra Seul e Pyongyang."
   ],
