   "id": "z64caed37",
   "sez": "mondo",
   "titolo": "Iran e Stati Uniti: accordo diplomatico ancora lontano secondo Teheran",
   "orig": "Iran-US deal still out of reach despite heightened diplomatic efforts",
   "lead": "Nonostante l'intensificarsi degli sforzi diplomatici a livello internazionale per evitare un'escalation del conflitto, un accordo formale tra l'Iran e gli Stati Uniti resta ancora lontano da raggiungere. Lo ha dichiarato un alto funzionario governativo iraniano, spiegando che Teheran ha fornito risposte concrete e che spetta ora a Washington fare i passi necessari per riaprire un dialogo costruttivo dopo le elezioni di metà mandato. Le discussioni mirano a contenere le tensioni belliche in Medio Oriente.",
   "more": [
    "I rapporti tra gli Stati Uniti e l'Iran sono segnati da decenni di contenziosi legati al programma nucleare iraniano, alle sanzioni economiche e alla stabilità regionale. Le trattative indirette cercano di prevenire scontri militari diretti e di favorire la sicurezza nel Medio Oriente."
   ],
