   "sez": "mondo",
   "titolo": "Georgia: il Movimento Nazionale Unito abbandona l'Alleanza dell'Opposizione",
   "orig": "UNM Confirms Quitting Opposition Alliance After Months of Infighting",
   "lead": "Il Movimento Nazionale Unito, principale partito d'opposizione ed ex forza di governo in Georgia, ha ufficialmente confermato l'uscita dall'Alleanza dell'Opposizione. La coalizione era stata formata nel mese di marzo da nove distinte forze politiche per contrastare la maggioranza di governo. La scissione giunge al termine di mesi di crescenti disaccordi interni ed estenuanti polemiche tra i vertici del movimento e gli altri membri dell'alleanza, accusati di aver denigrato l'azione politica del partito.",
   "more": [
    "Il panorama politico della Georgia è caratterizzato da una forte polarizzazione tra il partito di governo e i gruppi dell'opposizione. Le spaccature interne al fronte democratico rischiano di indebolire la capacità dei partiti di minoranza di presentare un programma unitario alle prossime consultazioni."
   ],
